<?php\n// modules/finance/payroll/PayrollProcessor.php - Core Business Logic Handler (Steps 5, 6, 7, 8)\n\nnamespace Finance\\Services;\nuse PDO;\nuse Finance\\Core\\DbUtility; \n\n/**\n * Orchestrates the entire financial posting process for a payroll run.\n */\nclass PayrollProcessor {\n    private DbUtility $dbUtil;\n    private PDO $pdo;\n\n    public function __construct(PDO $pdo, DbUtility $dbUtil) {\n        $this->pdo = $pdo;\n        $this->dbUtil = $dbUtil;\n    }\n\n    /**\n     * STEP 5: Validation - Checks if the payroll run is ready for accounting.\n     * @param int \$payrollRunId The ID of the payroll run from HRMS/Payroll.\n     * @return bool True if process can proceed.\n     */\n    public function canProcessRun(int $payrollRunId): bool {\n        // 1. Check status (Step 5) - Assume Payroll Status enum exists in DB table related to runs.\n        $statusSql = \"SELECT status FROM payroll_runs WHERE id = :run_id;\";\n        \$stmt = \$this->pdo->prepare(\$statusSql);\n        \$stmt->execute([':run_id' => \$payrollRunId]);\n        \$statusRecord = \$stmt->fetch(PDO::FETCH_ASSOC);\n\n        if (!\$statusRecord) {\n            error_log(\"Payroll Run ID $payrollRunId not found.\");\n            return false; // Not found\n        }\n\n        $allowedStatuses = ['APPROVED']; // Must be APPROVED or similar final state\n        if (!in_array(\$statusRecord['status'], $allowedStatuses)) {\n             error_log(\"Payroll Run ID $payrollRunId is in status '{$statusRecord['status']}'. Cannot post.\");\n             return false;\n        }\n        // Add checks for Period Control (Step 20) would go here: e.g., if period closed, return false.\n\n        return true;\n    }\n\n    /**\n     * STEP 6: Pre-Post View - Gathers summary data.\n     * @param int \$payrollRunId \n     * @return array|null Summary totals or null on failure.\n     */\n    public function previewPayrollData(int $payrollRunId): ?array {\n        // NOTE: This requires JOINs/SELECTS from the Payroll module tables that hold raw data (Gross, Allowances, Deductions).\n        // For now, we mock retrieval based on structure defined in Step 6.\n        \n        // In a real scenario, you query payroll_run_detail where run_id = :payrollRunId \n        $summary = [\n            'totalEmployees' => $this->fetchTotalEmployees($payrollRunId), // Needs implementation based on Payroll DB\n            'grossSalary'    => 50000.00, // MOCKED\n            'allowances'     => 15000.00, // MOCKED\n            'overtime'       => 3000.00,  // MOCKED\n            'employeeDeductions' => -8000.00, // MOCKED (negative) \n            'employerContributions' => 2000.00, // MOCKED\n            'netSalary'      => 15000.00, // Calculated: Gross + Allowances + Overtime - Deductions\n            'totalPayrollCost'=> 63000.00  // Total cost posted to GL (Gross + Employer Contribution)\n        ];\n\n        return $summary;\n    }\n\n    /**\n     * STEP 7 & 8: CORE POSTING - Generates journal entries and calls the Posting Engine.\n     * @param int \$payrollRunId The ID of the finalized payroll run.\n     * @param array $mappingConfig Config loaded from payroll_finance_mappings table.\n     * @return string|null Journal Entry ID if successful, else null.\n     */\n    public function postAccounting(int $payrollRunId, array $mappingConfig): ?string {\n        // 1. Construct the Journal Entries (Step 7)\n        $journalEntries = [\n            ['account_id' => 'SALARY_EXPENSE_ACCT', 'debit' => 0.0, 'credit' => 0.0], // Placeholder\n            ['account_id' => 'EMPLOYEE_PAYABLE_ACCT', 'debit' => 0.0, 'credit' => 15000.00], // Example Credit: Liability increase\n            // ... other entries based on mappingConfig logic ...\n        ];\n        \n        // In a full implementation, $mappingConfig is iterated here to build the exact debit/credit values.\n        \n        if (count($journalEntries) === 0) {\n            error_log(\"Failed to construct any journal entries for run ID $payrollRunId.\");\n            return null;\n        }\n\n        // 2. Call Posting Engine (Step 8)\n        $journalEntryId = $this->dbUtil->postToGeneralLedger($journalEntries);\n        \n        if (\$journalEntryId) {\n             // 3. Update status upon success (Crucial Step)\n            \$updateSql = \"UPDATE payroll_finance_postings SET journal_entry_id=:je_id, status='POSTED', posting_date=CURDATE() WHERE payroll_run_id=:pr_id;\";\n            if (\$this->dbUtil->execute(\$updateSql, ['je_id' => \$journalEntryId, 'pr_id' => $payrollRunId])) {\n                error_log(\"Successfully posted and updated status for Run ID $payrollRunId. JE ID: $journalEntryId\");\n                return $journalEntryId;\n            }\n        } \n        \n        return null; // Failed to update status or post.\n    }\n\n    // --- Private Helpers (Must read from Payroll Module's DB) ---\n    private function fetchTotalEmployees(int $payrollRunId): int {\n         // Implementation stub: Query the payroll module for run details\n         return 150; \n    }\n}\n?>"